/// `Mult`.
///
/// Cut: SYS, rGPR.
pub(super) fn Mult(word: u32, b: &mut Builder, st: &mut St) -> Result<(), LiftError> {
    const ENC: Encoding = Encoding::Mult;
    let w = u128::from(word);
    let pc = u128::from(b.pc());
    let s1: u128 = (w >> 21) & 0x1f;
    let s2: u128 = (w >> 16) & 0x1f;
    let v3 = st.gpr(b, (s1) as u8);
    let v4 = st.gpr(b, (s2) as u8);
    let v5 = b.extract(v3, 0, Width::new(32));
    let v6 = b.extract(v4, 0, Width::new(32));
    let v7 = b.sext(v5, Width::new(64));
    let v8 = b.sext(v6, Width::new(64));
    let v9 = b.bin(BinOp::Mul, v7, v8);
    let v10 = b.extract(v9, 32, Width::new(32));
    let v11 = b.sext(v10, Width::new(64));
    st.set_reg(b, "HI", v11, None);
    let v12 = b.extract(v9, 0, Width::new(32));
    let v13 = b.sext(v12, Width::new(64));
    st.set_reg(b, "LO", v13, None);
    Ok(())
}

/// `Multu`.
///
/// Cut: SYS, rGPR.
